"""A from-scratch preprocessing pipeline: sentence segmentation, tokenisation, stop words,
stemming vs lemmatisation."""
import re
text = ("Dr. Rao paid 3.14 dollars for coffee. She ran to the station! "
        "The studies were better than expected; the children's toys are running out.")
ABBREV = {"dr.", "mr.", "mrs.", "prof.", "e.g.", "i.e."}
def sentences(t):
    out, cur = [], ""
    for tok in re.findall(r"\S+\s*", t):
        cur += tok; w = tok.strip().lower()
        if re.search(r"[.!?]$", w) and w not in ABBREV and not re.fullmatch(r"\d+\.\d+", w.rstrip(".!?")):
            out.append(cur.strip()); cur = ""
    if cur.strip(): out.append(cur.strip())
    return out
def tokens(s):
    return re.findall(r"\d+\.\d+|\w+(?:'\w+)?|[^\w\s]", s)
STOP = {"the", "a", "an", "is", "are", "were", "was", "to", "for", "than", "she", "out"}
def stem(w):                                   # crude suffix stripping (Porter-like flavour)
    for suf, rep in (("sses", "ss"), ("ies", "i"), ("ing", ""), ("ed", ""), ("ly", ""), ("s", "")):
        if w.endswith(suf) and len(w) - len(suf) >= 3:
            w = w[: len(w) - len(suf)] + rep
            if suf == "ing" and len(w) > 3 and w[-1] == w[-2]: w = w[:-1]   # running -> run
            return w
    return w
LEMMA = {"ran": "run", "running": "run", "better": "good", "studies": "study", "children": "child",
         "were": "be", "are": "be", "toys": "toy", "paid": "pay", "expected": "expect", "dollars": "dollar", "children's": "child"}
for i, s in enumerate(sentences(text), 1):
    toks = tokens(s)
    content = [t for t in toks if re.match(r"\w", t) and not re.fullmatch(r"[\d.]+", t) and t.lower() not in STOP]
    print(f"sentence {i}: {s}")
    print("   tokens:      ", toks)
    print("   no stopwords:", content)
    print("   stems:       ", [stem(t.lower()) for t in content])
    print("   lemmas:      ", [LEMMA.get(t.lower(), t.lower()) for t in content])
print("\nNote 'studies' -> stem 'studi' (not a word) but lemma 'study'; 'better' -> lemma 'good' needs a dictionary.")

"""A tiny context-free grammar that makes structural ambiguity explicit, plus contingency-table metrics."""
from itertools import product
RULES = {"S": [["NP", "VP"]], "NP": [["N", "N"], ["N"]], "VP": [["V", "NP"], ["V", "PP"]], "PP": [["P", "NP"]]}
LEX = {"rice": ["N"], "flies": ["N", "V"], "like": ["V", "P"], "sand": ["N"]}
def parses(sym, words):
    """All parse trees of `sym` spanning exactly `words` (top-down, exhaustive)."""
    out = []
    if len(words) == 1 and sym in LEX.get(words[0], []):
        out.append(f"({sym} {words[0]})")
    for rhs in RULES.get(sym, []):
        if len(rhs) == 1:
            out += [f"({sym} {t})" for t in parses(rhs[0], words)]
        else:
            for k in range(1, len(words)):
                for l, r in product(parses(rhs[0], words[:k]), parses(rhs[1], words[k:])):
                    out.append(f"({sym} {l} {r})")
    return out
trees = parses("S", "rice flies like sand".split())
print(f"'Rice flies like sand' has {len(trees)} parses:")
for t in trees: print("  ", t)

# evaluation from a contingency table: a spam filter on 100 test emails
TP, FP, FN, TN = 40, 10, 5, 45
acc = (TP + TN) / 100; prec = TP / (TP + FP); rec = TP / (TP + FN); f1 = 2 * prec * rec / (prec + rec)
print(f"\nTP={TP} FP={FP} FN={FN} TN={TN}: accuracy {acc:.2f}, precision {prec:.2f}, recall {rec:.3f}, F1 {f1:.3f}")
print("If only 5 of 100 emails were spam, predicting 'not spam' always would score 95% accuracy with 0 recall.")
